 Begin CmpMap 	# Compound Mapping
    Nin = 3 	# Number of input coordinates
 IsA Mapping 	# Mapping between coordinate systems
    MapA = 	# First component Mapping
       Begin CmpMap 	# Compound Mapping
          Nin = 3 	# Number of input coordinates
       IsA Mapping 	# Mapping between coordinate systems
          MapA = 	# First component Mapping
             Begin CmpMap 	# Compound Mapping
                Nin = 3 	# Number of input coordinates
             IsA Mapping 	# Mapping between coordinate systems
                MapA = 	# First component Mapping
                   Begin CmpMap 	# Compound Mapping
                      Nin = 3 	# Number of input coordinates
                   IsA Mapping 	# Mapping between coordinate systems
                      MapA = 	# First component Mapping
                         Begin CmpMap 	# Compound Mapping
                            Nin = 3 	# Number of input coordinates
                         IsA Mapping 	# Mapping between coordinate systems
                            MapA = 	# First component Mapping
                               Begin WinMap 	# Map one window on to another
                                  Nin = 3 	# Number of input coordinates
                               IsA Mapping 	# Mapping between coordinate systems
                                  Sft1 = -1000 	# Shift for axis 1
                                  Sft3 = -1 	# Shift for axis 3
                               End WinMap
                            MapB = 	# Second component Mapping
                               Begin MatrixMap 	# Matrix transformation
                                  Nin = 3 	# Number of input coordinates
                               IsA Mapping 	# Mapping between coordinate systems
                                  Form = "Unit" 	# Matrix storage form
                               End MatrixMap
                         End CmpMap
                      MapB = 	# Second component Mapping
                         Begin MatrixMap 	# Matrix transformation
                            Nin = 3 	# Number of input coordinates
                         IsA Mapping 	# Mapping between coordinate systems
                            M0 = 0.0769230769230769 	# Forward matrix value
                            M1 = 1.0000000000000004 	# Forward matrix value
                            M2 = 0.00048828125 	# Forward matrix value
                            IM0 = 13.000000000000004 	# Inverse matrix value
                            IM1 = 0.99999999999999956 	# Inverse matrix value
                            IM2 = 2048 	# Inverse matrix value
                            Form = "Diagonal" 	# Matrix storage form
                         End MatrixMap
                   End CmpMap
                MapB = 	# Second component Mapping
                   Begin UnitMap 	# Unit (null) Mapping
                      Nin = 3 	# Number of input coordinates
                   IsA Mapping 	# Mapping between coordinate systems
                   End UnitMap
             End CmpMap
          MapB = 	# Second component Mapping
             Begin CmpMap 	# Compound Mapping
                Nin = 3 	# Number of input coordinates
             IsA Mapping 	# Mapping between coordinate systems
                Series = 0 	# Component Mappings applied in parallel
                MapA = 	# First component Mapping
                   Begin CmpMap 	# Compound Mapping
                      Nin = 2 	# Number of input coordinates
                   IsA Mapping 	# Mapping between coordinate systems
                      Series = 0 	# Component Mappings applied in parallel
                      MapA = 	# First component Mapping
                         Begin UnitMap 	# Unit (null) Mapping
                            Nin = 1 	# Number of input coordinates
                         IsA Mapping 	# Mapping between coordinate systems
                         End UnitMap
                      MapB = 	# Second component Mapping
                         Begin UnitMap 	# Unit (null) Mapping
                            Nin = 1 	# Number of input coordinates
                         IsA Mapping 	# Mapping between coordinate systems
                         End UnitMap
                   End CmpMap
                MapB = 	# Second component Mapping
                   Begin UnitMap 	# Unit (null) Mapping
                      Nin = 1 	# Number of input coordinates
                   IsA Mapping 	# Mapping between coordinate systems
                   End UnitMap
             End CmpMap
       End CmpMap
    MapB = 	# Second component Mapping
       Begin CmpMap 	# Compound Mapping
          Nin = 3 	# Number of input coordinates
       IsA Mapping 	# Mapping between coordinate systems
          Series = 0 	# Component Mappings applied in parallel
          MapA = 	# First component Mapping
             Begin CmpMap 	# Compound Mapping
                Nin = 2 	# Number of input coordinates
             IsA Mapping 	# Mapping between coordinate systems
                Series = 0 	# Component Mappings applied in parallel
                MapA = 	# First component Mapping
                   Begin ShiftMap 	# Shift each coordinate axis
                      Nin = 1 	# Number of input coordinates
                   IsA Mapping 	# Mapping between coordinate systems
                      Sft1 = 76.884615384615373 	# Shift for axis 1
                   End ShiftMap
                MapB = 	# Second component Mapping
                   Begin ShiftMap 	# Shift each coordinate axis
                      Nin = 1 	# Number of input coordinates
                   IsA Mapping 	# Mapping between coordinate systems
                      Sft1 = -0.5 	# Shift for axis 1
                   End ShiftMap
             End CmpMap
          MapB = 	# Second component Mapping
             Begin ShiftMap 	# Shift each coordinate axis
                Nin = 1 	# Number of input coordinates
             IsA Mapping 	# Mapping between coordinate systems
                Sft1 = 0.000244140625 	# Shift for axis 1
             End ShiftMap
       End CmpMap
 End CmpMap
